const listeners = new Set();
export function getSettingsSnapshot(){return settingsStore;}
export function subscribeSettings(listener){listeners.add(listener);return()=>listeners.delete(listener);}
export function updateSettings(patch){settingsStore={...settingsStore,...patch};listeners.forEach(fn=>fn());window.dispatchEvent(new CustomEvent('lumi54:settings',{detail:settingsStore}));}
export function isModelAvailable(model,state=settingsStore){const p=state.providers.find(p=>p.id===model.provider);return model.enabled&&model.status==='available'&&p?.enabled&&p.status==='ready'&&p.accounts.some(a=>a.enabled);}

